learn=[('Enable and detect AskUserQuestion', 'Keep AskUserQuestion in an explicit tools list and route that tool name to a dedicated question handler. Normal tool permission requests belong in a separate branch. An allow entry does not provide the missing human answers.'), ('Present Claude’s actual questions', 'Parse questions, header, options and multiSelect. Claude owns the wording and choices. The host renders radio buttons or checkboxes and offers a custom Other answer without appending new SDK questions.'), ('Return full-text answer keys', 'Preserve the original questions array. Map each full question text to its selected label, joined multi-select labels or the student’s custom answer. A header or option index is not the SDK answer key.'), ('Compare custom text with a general reply', 'Other belongs in answers[question]. A general response dismisses the structured card and uses the optional response field instead. The UI supports both, and offline tests distinguish their returned shapes.'), ('Render optional previews', 'TypeScript toolConfig can request HTML or Markdown previews. Display only previews the model actually supplies. The SDK rejects certain unsafe HTML; the browser also sanitizes fragments and uses a sandboxed iframe with a restrictive content policy.'), ('Handle plan mode, cancellation and limits', 'Answer real questions before a read-only plan. Abort and timeout settle the waiting promise without inventing an answer. The UI is a local teaching sample; a long-lived production workflow may need documented deferred execution and authenticated request ownership.')]
env='ANTHROPIC_API_KEY=your_api_key\nCLAUDE_MODEL=claude-sonnet-4-6\nPORT=3131\n# Windows only, if needed:\n# CLAUDE_CODE_GIT_BASH_PATH=C:/Program Files/Git/bin/bash.exe\n'
runsteps=[('Prerequisites', 'Use Node.js 24+, API credit and a supported model. Windows may require Git Bash. Python is needed only to regenerate the student pages.', 'node --version\nnpm --version'), ('Install and create your .env file', 'From presentations enter the application, install locked dependencies, preserve an existing .env and enter your model key privately.', 'cd .\\agent-sdk\\lesson31-clarifying-questions\nnpm ci\nif (!(Test-Path .env)) { Copy-Item .env.example .env }\nnotepad .env'), ('Start the application', 'Keep the terminal open and visit port 3131. Navigate between the lab, learning goals, setup, UML architecture and code walkthrough.', 'npm start\n# http://127.0.0.1:3131'), ('Answer actual generated questions', 'Run Single select, choose an option and submit. Repeat with Multi-select and Question batch. Observe how the full question texts map to actual selected labels. An explicitly scripted CLI demonstration requires the flag below.', 'npm run sample:env -- single --answer-first\nnpm run sample:env -- multi --answer-first\nnpm run sample:env -- batch --answer-first'), ('Try your own words and previews', 'In Other select the host-provided custom-answer control and type your own words. HTML and Markdown experiments display optional previews actually generated by Claude. The general-reply section sends response instead of per-question answers.', 'npm run sample:env -- free-text --answer-first\nnpm run sample:env -- html --answer-first\nnpm run sample:env -- markdown --answer-first'), ('Compare plan mode, allow entries and cancellation', 'Answer the plan-mode question before reading the plan. Confirm the allow-entry case still needs a human answer. In Cancel, cancel while the callback waits and inspect the empty answer map and pending count.', 'npm run sample:env -- plan --answer-first\nnpm run sample:env -- preallowed --answer-first\nnpm test')]
specs=[('Validate the selected classroom task', 'src/modes.ts', 'export function validateConfig', 'The host accepts a listed experiment. The student does not replace the tools list, permission mode or SDK tool configuration through browser input.', 0, 1, 7), ('Enable the actual question tool', 'src/agent.ts', 'tools: ["Read", "AskUserQuestion"]', 'An explicit tools list includes AskUserQuestion. The allow-entry comparison still needs human answers. HTML and Markdown use the real TypeScript preview configuration.', 1, 2, 8), ('Start one real streaming query', 'src/agent.ts', 'const active = query', 'One SDK query generates the actual question payload, waits for answers and continues. The async input remains alive during the callback; it is released during cleanup.', 1, 2, 3), ('Route the clarifying-question callback', 'src/agent.ts', 'if (toolName !== "AskUserQuestion")', 'Branch on the actual tool name. Unrelated approval requests are denied by this dedicated handler; a question request is parsed and sent to the UI.', 2, 1, 9), ('Validate without rewriting the questions', 'src/questions.ts', 'export function parseQuestions', 'Check question and option shapes, limits and duplicate texts. Return the original array and objects. The host never appends its own question to Claude’s tool input.', 1, 1, 8), ('Register a pending resolver and emit SSE', 'src/questions.ts', 'pending.set(id,', 'Register the resolver before sending the request to the browser. Abort and timeout resolve cancellation, remove the request and clear its timer and listener.', 1, 3, 9), ('Render actual options as radio or checkbox controls', 'src/question-form.ts', 'input.type = q.multiSelect', 'Use radio buttons for a single choice and checkboxes for multi-select. Labels and descriptions come from the actual SDK options, with no preselected answer.', 1, 0, 8), ('Render optional HTML and Markdown previews', 'src/previews.ts', 'frame.setAttribute("sandbox"', 'Sanitize model-generated fragments, isolate HTML in a sandboxed iframe and block external content through its content policy. Missing previews remain visibly absent.', 1, 0, 6), ('Collect answers using full question text', 'src/question-form.ts', 'const selections:', 'The form collects each selected label or custom answer under the original full question text. Other is a host UI control, not a new question or a literal answer label.', 0, 1, 10), ('Resolve the answer POST once', 'src/questions.ts', 'export function resolveAnswers', 'Look up the pending request, validate the submitted selection against its original questions, then settle it once. Invalid submissions leave the same request waiting; stale IDs are rejected.', 0, 3, 7), ('Map selected labels and custom text', 'src/questions.ts', 'answers[q.question] = s.other.trim();', 'Map a custom answer to the original question text. Otherwise join the actual selected labels with comma-space for the SDK response. A general response takes a separate branch.', 1, 1, 8), ('Preserve questions in updatedInput', 'src/agent.ts', 'const updatedInput =', 'Return allow with the unchanged original questions and validated answers, or the optional general response. Claude receives this real tool result and continues with the student’s choices.', 1, 2, 10), ('Record evidence and clean up', 'src/agent.ts', 'const files = await workspace.inspect();', 'Record actual question and preview counts, answer mappings, callback calls, pending state and the unchanged fixture. No generated answer or preview is fabricated.', 4, 1, 9)]
document('/','Clarifying <em>questions.</em>','Render Claude’s questions, collect actual answers and let the agent continue.','<div class="flow"><div><b>01 · Ask</b><p>Claude generates the questions</p></div><span>→</span><div><b>02 · Choose</b><p>Select options or use your words</p></div><span>→</span><div><b>03 · Continue</b><p>The SDK receives actual answers</p></div></div><section class="panel" id="controls"><h2>Explore clarifying questions</h2><p id="configuration" class="meta">Checking local server…</p><label for="mode">Question experiment</label><select id="mode"><option value="single">Single select · one generated question</option><option value="multi">Multi-select · choose several labels</option><option value="batch">Question batch · two questions together</option><option value="free-text">Other · answer in your own words</option><option value="html">HTML previews · compare real mockups</option><option value="markdown">Markdown previews · compare real layouts</option><option value="plan">Plan mode · clarify before proposing</option><option value="preallowed">Allow entry · human answers still required</option><option value="cancel">Cancel · no fabricated answers</option></select><label for="prediction">Predict or observe the tool outcome</label><select id="prediction"><option value="execute">Execute · answer and continue</option><option value="block">Block · cancel without answers</option><option value="mixed">Mixed · inspect native feedback</option><option value="observe">Observe · inspect runtime-dependent behavior</option></select><button id="run" class="primary" disabled>Run question experiment →</button><p class="meta">Questions and previews come from the actual model, not a fixed host questionnaire. Nothing is selected or submitted automatically. Requests expire after two minutes. No files are written.</p></section><section class="step" id="question-panel" hidden><h2>Answer Claude’s actual questions</h2><p id="request-meta" class="meta"></p><p id="question-status" class="note" aria-live="polite"></p><form id="question-form"><div id="questions-container"></div><div class="actions"><button id="submit-answers" class="primary" type="submit">Send my answers</button><button id="cancel-question" type="button">Cancel without answering</button></div></form><details id="general-reply"><summary>Reply in general instead of choosing options</summary><label for="general-response">Your reply · sent as response, not as an answer to one question</label><textarea id="general-response" maxlength="2000"></textarea><button id="send-response">Send general reply</button></details><details><summary>Inspect the original SDK questions</summary><pre class="json-view"><code id="question-input" class="language-json">{}</code></pre></details></section><div class="workspace"><section class="panel" id="outcome"><h2 id="status" aria-live="polite">Ready</h2><p>Latest SDK-reported cost: <strong id="cost">—</strong></p><p class="meta">Session: <span id="session">—</span></p><div id="answer" class="markdown-body"></div><p id="notice" class="note"></p></section><section class="panel" id="option-panel"><h2>Options actually passed</h2><pre class="json-view"><code id="options" class="language-json">{}</code></pre><p>Inspect the explicit tools list, actual preview format and SDK-reported mode.</p></section></div><section class="step" id="answers-panel"><h2>Actual answers returned to the SDK</h2><pre class="json-view"><code id="answer-summary" class="language-json">{}</code></pre><p>The original questions are preserved. A general response is distinct from per-question answers.</p></section><section class="step" id="pipeline-panel"><h2>Clarifying-question workflow</h2><p>Inspect the request, choose a response and verify the actual result.</p><div class="grid"><article class="card"><h3>Enable</h3><p>Include AskUserQuestion in an explicit tools list.</p></article><article class="card"><h3>Detect</h3><p>Branch on the actual toolName in canUseTool.</p></article><article class="card"><h3>Render</h3><p>Use radio buttons, checkboxes and optional previews.</p></article><article class="card"><h3>Map</h3><p>Use full question text as each answer key.</p></article><article class="card"><h3>Return</h3><p>Preserve questions and send answers in updatedInput.</p></article><article class="card"><h3>Cancel</h3><p>Settle and remove pending requests without guessing.</p></article></div></section><section class="step" id="configuration-panel"><h2>Actual question configuration</h2><label for="configuration-file">Configuration projection</label><select id="configuration-file"></select><pre class="json-view"><code id="configuration-content" class="language-json">{}</code></pre><p>Only the selected question, preview and permission-mode configuration is shown. The model key stays private.</p></section><section class="step" id="discovery-panel"><h2>Actual SDK initialization</h2><pre class="json-view"><code id="discovery" class="language-json">{}</code></pre><p>This is the SDK initialization payload. A requested mode and a reported mode are separate evidence.</p></section><section class="step" id="trace-panel"><h2>Actual hooks, callback calls and turns</h2><pre class="json-view"><code id="trace" class="language-json">{}</code></pre><p>The host passes only AskUserQuestion and the fixed lesson fixture read. It never auto-fills an answer.</p></section><section class="step" id="native-panel"><h2>Actual native tool feedback</h2><pre class="json-view"><code id="native" class="language-json">{}</code></pre><p>Inspect the actual AskUserQuestion tool result and the follow-up read. The model receives the real answer mapping.</p></section><section class="step" id="evidence-panel"><h2>Questions, answers and independent evidence</h2><pre class="json-view"><code id="evidence" class="language-json">{}</code></pre><p>Inspect actual generated questions, selected answers, preview counts, preserved questions, cancellation and the unchanged fixture.</p></section><section class="step" id="comparison-panel"><h2>Compare this browser’s question experiments</h2><p id="verdict">Predict execute, block, mixed or observe before running. Select actual options or use your own words, then submit explicitly.</p><div class="table"><table><thead><tr><th>Experiment</th><th>Reference behavior</th><th>Prediction</th><th>Observed</th><th>Callbacks</th><th>Questions</th><th>Actual answers</th></tr></thead><tbody id="history"></tbody></table></div><button id="download">Download redacted observations</button></section><section class="step" id="event-panel"><h2>Actual SDK messages</h2><ul id="events"></ul></section>','<script type="module" src="/client.js"></script>')
document('/learn.html','What you <em>will learn.</em>','Enable the question tool and preserve the original questions and answer keys.',cards(learn))
